-- GenDB engine variant Q17-conjunct_permutation: template q17.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  SUM(l_extendedprice) / 7.0 AS avg_yearly
FROM lineitem, part
WHERE
  l_quantity < (
    SELECT
      0.2 * AVG(l_quantity)
    FROM lineitem
    WHERE
      l_partkey = p_partkey
  )
  AND p_container = $2
  AND p_brand = $1
  AND p_partkey = l_partkey
